"""
语义分块模块单元测试
"""
import pytest
from src.document.chunker import SemanticChunker, TextChunk


class TestSemanticChunker:
    """语义分块器测试"""
    
    @pytest.fixture
    def chunker(self):
        return SemanticChunker(chunk_size=512, chunk_overlap=64)
    
    def test_chunk_short_text(self, chunker):
        """测试短文本不分块"""
        text = "这是一段很短的文本。"
        chunks = chunker.chunk(text, "doc_001")
        
        assert len(chunks) == 1
        assert chunks[0].text == text
        assert chunks[0].start_pos == 0
        assert chunks[0].end_pos == len(text)
    
    def test_chunk_empty_text(self, chunker):
        """测试空文本"""
        chunks = chunker.chunk("", "doc_001")
        assert len(chunks) == 0
    
    def test_chunk_whitespace_only(self, chunker):
        """测试只有空白字符"""
        chunks = chunker.chunk("   \n\n   ", "doc_001")
        assert len(chunks) == 0
    
    def test_chunk_long_text(self, chunker):
        """测试长文本分块"""
        # 生成超过chunk_size的文本
        text = "这是一个测试句子。" * 100
        chunks = chunker.chunk(text, "doc_001")
        
        assert len(chunks) > 1
        # 验证每个块的大小
        for chunk in chunks:
            assert len(chunk.text) <= chunker.chunk_size
    
    def test_chunk_paragraph_boundary(self, chunker):
        """测试段落边界保留"""
        text = "第一段内容。\n\n第二段内容。\n\n第三段内容。"
        chunks = chunker.chunk(text, "doc_001")
        
        # 短文本应该保留段落结构
        assert len(chunks) == 1
        assert "第一段" in chunks[0].text
        assert "第二段" in chunks[0].text
    
    def test_chunk_id_generation(self, chunker):
        """测试块ID生成"""
        text = "测试内容。"
        chunks = chunker.chunk(text, "doc_001")
        
        assert len(chunks) == 1
        assert "doc_001" in chunks[0].id
        assert len(chunks[0].id) == 32  # MD5哈希长度
    
